/* ============================================================
   thaisound4.js — เสียงจริงของวงกลองปู่เจ่และกลองสะบัดชัยของชมรม (อัดจริง 3 พ.ย. 2569)
   วงกลองปู่เจ่  : กลองปู่เจ่ชุด 3 ใบ (ใบใหญ่ 104 Hz · ใบกลาง 203 Hz · ใบเล็ก 367 Hz) + ฉาบ + ฆ้องราว
   กลองสะบัดชัย : กลองสะบัดชัย (หน้ากลอง 175 Hz · ขอบกลอง 737 Hz) + ฉาบ + ฆ้องราว   ← คนละวงกับปู่เจ่
                  สองวงนี้ใช้ร่วมกันแค่ “ฉาบ” กับ “ฆ้องราว” เท่านั้น ตัวกลองคนละชนิดกัน
   ฆ้องราว      : คลิปที่อัดไว้มีเฉพาะลูกใหญ่ (259 Hz) จึงใช้เสียงเดียว ไม่แปลงระดับเสียงให้เพี้ยน
   ทุกเสียงตัดไว้ใบละ 2–3 ลูก สลับกันเวลาตีซ้ำ (round-robin) และสุ่มระดับ/ระดับเสียงเล็กน้อย
   จึงไม่เหมือนเสียงก๊อปวางเวลาตีรัว · หัวเสียงเก็บของดิบไว้ ลดเสียงห้องเฉพาะหางเสียง
     TS4.init(ac,out) -> Promise (เสร็จเมื่อถอดรหัสเสียงครบ ใช้รอก่อนอัดไฟล์)
     TS4.pujae(k,t,v,out)    k 0 ใบใหญ่ · 1 ใบกลาง · 2 ใบเล็ก
     TS4.chab(k,t,v,out)     k 0 เปิด · 1 ปิด
     TS4.khongrao(t,v,out)   ฆ้องราว (เสียงเดียว) · เรียกแบบเดิม khongrao(k,t,v,out) ก็ยังได้
     TS4.sabat(k,t,v,out)    k 0 หน้ากลอง · 1 ขอบกลอง
   พัฒนาโดย นายนนทพัทธ์ วงค์มูล 2026
   ============================================================ */
(function(){
'use strict';
if(window.TS4)return;
const SRC={"pj_lo0": "data:audio/mpeg;base64,", "pj_lo1": "data:audio/mpeg;base64,", "pj_lo2": "data:audio/mpeg;base64,", "pj_mid0": "data:audio/mpeg;base64,", "pj_mid1": "data:audio/mpeg;base64,", "pj_mid2": "data:audio/mpeg;base64,", "pj_hi0": "data:audio/mpeg;base64,", "pj_hi1": "data:audio/mpeg;base64,", "pj_hi2": "data:audio/mpeg;base64,", "cb_open0": "data:audio/mpeg;base64,", "cb_open1": "data:audio/mpeg;base64,", "cb_shut0": "data:audio/mpeg;base64,", "cb_shut1": "data:audio/mpeg;base64,", "kr_big": "data:audio/mpeg;base64,", "sb_hit0": "data:audio/mpeg;base64,", "sb_hit1": "data:audio/mpeg;base64,", "sb_hit2": "data:audio/mpeg;base64,", "sb_rim": "data:audio/mpeg;base64,"};

const GRP={pj_lo:['pj_lo0','pj_lo1','pj_lo2'],pj_mid:['pj_mid0','pj_mid1','pj_mid2'],pj_hi:['pj_hi0','pj_hi1','pj_hi2'],
  cb_open:['cb_open0','cb_open1'],cb_shut:['cb_shut0','cb_shut1'],kr:['kr_big'],sb_hit:['sb_hit0','sb_hit1','sb_hit2'],sb_rim:['sb_rim']};
const KEYS=Object.keys(SRC);
let AC=null,OUT=null,B={},RAW=null,RDY=null;
const RR={};Object.keys(GRP).forEach(g=>RR[g]=0);
/* โหลดไฟล์เสียงครั้งเดียว แล้วถอดรหัสใหม่ทุกครั้งที่เปลี่ยน AudioContext
   (ตอนอัดไฟล์ต้องใช้ OfflineAudioContext คนละตัว ถ้าไม่ถอดใหม่เสียงจะหาย) */
function fetchAll(){
  if(RAW)return RAW;
  RAW=Promise.all(KEYS.map(k=>fetch(SRC[k]).then(r=>r.arrayBuffer()).then(ab=>[k,ab])))
    .then(a=>{const o={};a.forEach(([k,ab])=>o[k]=ab);return o});
  return RAW}
function init(ac,out){
  if(AC===ac){if(out)OUT=out;return RDY||Promise.resolve()}
  AC=ac;OUT=out||ac.destination;const my=ac;
  RDY=fetchAll().then(raw=>Promise.all(KEYS.map(k=>new Promise(res=>{
      try{my.decodeAudioData(raw[k].slice(0),b=>res([k,b]),()=>res(null))}catch(e){res(null)}}))))
    .then(list=>{if(AC!==my)return;const nb={};
      list.forEach(x=>{if(!x)return;const k=x[0],b=x[1],d=b.getChannelData(0);
        let m=0;for(let i=0;i<d.length;i++){const v=d[i]<0?-d[i]:d[i];if(v>m)m=v}
        let s=0;while(s<d.length&&Math.abs(d[s])<m*.05)s++;
        nb[k]={b:b,off:Math.max(0,s/b.sampleRate-.004)}});
      B=nb}).catch(()=>{});
  return RDY}
const whenReady=()=>RDY||Promise.resolve();
const ready=k=>!!(k?B[k]:KEYS.every(x=>B[x]));
function one(key,t,v,rate,out,dur){
  const s=B[key];if(!AC||!s)return false;t=Math.max(t||0,AC.currentTime);
  const n=AC.createBufferSource(),g=AC.createGain();n.buffer=s.b;n.playbackRate.value=rate||1;
  g.gain.setValueAtTime(v==null?1:v,t);
  if(dur){g.gain.setValueAtTime(v==null?1:v,t+Math.max(.02,dur-.05));g.gain.linearRampToValueAtTime(0,t+dur)}
  n.connect(g);g.connect(out||OUT);n.start(t,s.off);if(dur)n.stop(t+dur+.05);return true}
/* ตีลูกถัดไปของเสียงนั้น สลับใบและขยับระดับ/ความดังนิดหน่อยให้เหมือนคนตีจริง */
function hit(grp,t,v,out,dur,rate){
  const g=GRP[grp];if(!g)return false;
  const k=g[RR[grp]++%g.length];
  const r=(rate||1)*(1+(Math.random()-.5)*.03);
  return one(k,t,(v==null?1:v)*(1+(Math.random()-.5)*.14),r,out,dur)}
const cl=(k,n)=>Math.max(0,Math.min(n,k|0));
window.TS4={init,whenReady,ready,KHONG:259,
  pujae:(k,t,v,out,dur)=>hit(['pj_lo','pj_mid','pj_hi'][cl(k,2)],t,v,out,dur),
  chab:(k,t,v,out,dur)=>hit(k?'cb_shut':'cb_open',t,v,out,dur),
  /* ฆ้องราว: เสียงเดียว (ลูกใหญ่) รับได้ทั้ง khongrao(t,v,out) และแบบเดิม khongrao(k,t,v,out) */
  khongrao:function(a,b,c,d){
    if(typeof b==='number'&&typeof c==='number')return hit('kr',b,c,d);
    return hit('kr',a,b,c)},
  sabat:(k,t,v,out,dur)=>hit(k?'sb_rim':'sb_hit',t,v,out,dur),
  cut:(name,t,v,dur,out)=>hit(name,t,v,out,dur)};
})();
